// Shared i18n helpers + renderers for both praxis/5-achtsamkeitsuebungen.html and
// praxis/14-achtsamkeitsuebungen.html — identical markup/behavior, only the data
// differs, so this is the one place that owns how a training list (and its intro
// text) renders and how both respond to the header's DE/ENG/VI switch.
var EIAB_TRAININGS_LANG_MAP = { DE: 'de', ENG: 'en', VI: 'vi' };

function eiabTrainingsCurrentLang() {
  var stored = (window.EIAB_I18N && window.EIAB_I18N.getLang()) || 'DE';
  return EIAB_TRAININGS_LANG_MAP[stored] || 'de';
}

function eiabTrainingsEsc(s) {
  return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
  });
}

// Same fallback chain as person.html's tlList(): try the selected language, then
// German, then English, then Vietnamese — first non-empty array wins, so text
// whose translation hasn't arrived yet still shows real content instead of a
// blank paragraph.
function eiabTrainingsTlList(field) {
  var order = [eiabTrainingsCurrentLang(), 'de', 'en', 'vi'];
  for (var i = 0; i < order.length; i++) {
    var arr = field[order[i]];
    if (arr && arr.length) return arr;
  }
  return [];
}

function eiabTrainingsTl(field) {
  var order = [eiabTrainingsCurrentLang(), 'de', 'en', 'vi'];
  for (var i = 0; i < order.length; i++) {
    if (field[order[i]]) return field[order[i]];
  }
  return '';
}

window.EIAB_RENDER_TRAININGS = function (mountEl, trainings) {
  function render() {
    mountEl.innerHTML = trainings.map(function (t, i) {
      return (
        '<article class="training">' +
          '<div class="tnum">' + (i + 1) + '</div>' +
          '<div>' +
            '<h3>' + eiabTrainingsEsc(eiabTrainingsTl(t.title)) + '</h3>' +
            eiabTrainingsTlList(t.body).map(function (p) { return '<p>' + eiabTrainingsEsc(p) + '</p>'; }).join('') +
          '</div>' +
        '</article>'
      );
    }).join('');
  }
  render();
  window.addEventListener('eiab:langchange', render);
};

// Renders a translatable intro paragraph (e.g. EIAB_FIVE_MINDFULNESS_INTRO) into
// `introEl`, following the header's language switch the same way the training
// list itself does.
window.EIAB_RENDER_TRAININGS_INTRO = function (introEl, introField) {
  function render() {
    introEl.innerHTML = eiabTrainingsTlList(introField).map(function (p) {
      return '<p>' + eiabTrainingsEsc(p) + '</p>';
    }).join('');
  }
  render();
  window.addEventListener('eiab:langchange', render);
};
